cd /private/var/folders/yw/fbsfvfm95956m4m6yfd49z_c0000gn/T/tair-expanded-project-h91tgtmd/workspace && node --input-type=module -e "
import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup preserving order and first occurrence
console.log(JSON.stringify(uniqueStrings(['a', 'b', 'a', 'c', 'b'])));

// Case-insensitive dedup, original spelling preserved
console.log(JSON.stringify(uniqueStrings(['Apple', 'apple', 'APPLE', 'Banana', 'banana'])));

// Whitespace not trimmed
console.log(JSON.stringify(uniqueStrings([' a', 'a', 'a ', ' a'])));

// Input not mutated
const input = ['x', 'X', 'y', 'x'];
const out = uniqueStrings(input);
console.log('input unchanged:', JSON.stringify(input) === JSON.stringify(['x', 'X', 'y', 'x']));
console.log('output:', JSON.stringify(out));

// Empty array
console.log(JSON.stringify(uniqueStrings([])));

// Mixed case with distinct keys
console.log(JSON.stringify(uniqueStrings(['Hello', 'World', 'hello', 'world', 'HELLO'])));
"

